        [TestCase("def g():\n    try:\n        yield 1\n    except ValueError as e:\n        print('caught', e)\n        yield 'recovered'\n    yield 'after'\nit = g()\nprint(next(it))\nprint(it.throw(ValueError('boom')))\nprint(next(it))", "1\ncaught boom\nrecovered\nafter", TestName = "throw_caught_inside")]
