        [TestCase("def g():\n    try:\n        yield 1\n    finally:\n        print('cleanup')\nit = g()\nnext(it)\ntry:\n    it.throw(RuntimeError('fatal'))\nexcept RuntimeError as e:\n    print('RuntimeError', e)\nprint(list(it))\ntry:\n    next(it)\nexcept StopIteration:\n    print('done')", "cleanup\nRuntimeError fatal\n[]\ndone", TestName = "throw_uncaught_propagates_and_finishes")]
        [TestCase("def g():\n    yield 1\nit = g()\ntry:\n    it.throw(ValueError('early'))\nexcept ValueError as e:\n    print('ValueError', e)\nprint(list(it))\nit2 = g()\nlist(it2)\ntry:\n    it2.throw(KeyError('late'))\nexcept KeyError as e:\n    print('KeyError')", "ValueError early\n[]\nKeyError", TestName = "throw_before_start_and_after_end")]
        [TestCase("def g():\n    yield 1\nit = g()\nnext(it)\ntry:\n    it.throw(5)\nexcept TypeError:\n    print('TypeError')\ntry:\n    it.throw(int)\nexcept TypeError:\n    print('TypeError')", "TypeError\nTypeError", TestName = "throw_bad_argument")]
        [TestCase("class MyErr(Exception):\n    pass\ndef g():\n    try:\n        yield 1\n    except MyErr as e:\n        print('MyErr', e.args)\n        yield 2\nit = g()\nnext(it)\nprint(it.throw(MyErr, 'x'))\nit = g()\nnext(it)\nprint(it.throw(MyErr('y')))", "MyErr ('x',)\n2\nMyErr ('y',)\n2", TestName = "throw_script_exception_class")]
        [TestCase("def g():\n    try:\n        yield 1\n        yield 2\n    finally:\n        print('finally ran')\nit = g()\nprint(next(it))\nprint(it.close())\nprint(list(it))\nit.close()", "1\nfinally ran\nNone\n[]", TestName = "close_runs_finally")]
