        [TestCase("def g():\n    try:\n        yield 1\n    finally:\n        print('never')\nit = g()\nit.close()\nprint(list(it))\nit2 = g()\nnext(it2)\nit2.close()\nit2.close()\nprint('ok')", "[]\nnever\nok", TestName = "close_before_start_and_twice")]
        [TestCase("def g():\n    try:\n        yield 1\n    finally:\n        raise ValueError('from finally')\nit = g()\nnext(it)\ntry:\n    it.close()\nexcept ValueError as e:\n    print('ValueError', e)", "ValueError from finally", TestName = "close_with_error_in_finally")]
        [TestCase("def g():\n    try:\n        for i in range(10):\n            yield i\n    finally:\n        print('cleanup at', i)\nit = g()\nfor x in it:\n    if x == 2:\n        break\nit.close()\nprint('after close')", "cleanup at 2\nafter close", TestName = "close_in_for_break_pattern")]
        [TestCase("def g():\n    yield 1\n    return 'result'\nit = g()\nnext(it)\ntry:\n    next(it)\nexcept StopIteration as e:\n    print('StopIteration', e.value, e.args)\ntry:\n    next(it)\nexcept StopIteration as e:\n    print(e.value)\ndef h():\n    return 5\n    yield\ntry:\n    next(h())\nexcept StopIteration as e:\n    print(e.value)", "StopIteration result ('result',)\nNone\n5", TestName = "stopiteration_value_from_return")]
        [TestCase("def inner():\n    yield 1\n    yield 2\n    return 'inner done'\ndef outer():\n    result = yield from inner()\n    print('inner returned', result)\n    return 'outer done'\nprint(list(outer()))\nit = outer()\nnext(it); next(it)\ntry:\n    next(it)\nexcept StopIteration as e:\n    print(e.value)", "inner returned inner done\n[1, 2]\ninner returned inner done\nouter done", TestName = "stopiteration_value_via_yield_from")]
