        [TestCase("def inner():\n    x = yield 'first'\n    print('inner got', x)\n    y = yield 'second'\n    print('inner got', y)\n    return 'end'\ndef outer():\n    r = yield from inner()\n    print('outer got', r)\n    z = yield 'third'\n    print('outer got', z)\nit = outer()\nprint(next(it))\nprint(it.send('A'))\nprint(it.send('B'))\ntry:\n    it.send('C')\nexcept StopIteration:\n    print('finished')", "first\ninner got A\nsecond\ninner got B\nouter got end\nthird\nouter got C\nfinished", TestName = "send_forwarded_through_yield_from")]
        [TestCase("def a():\n    v = yield 'a1'\n    print('a got', v)\n    return 'a-result'\ndef b():\n    r = yield from a()\n    w = yield 'b1'\n    print('b got', w)\n    return r + '/b'\ndef c():\n    r = yield from b()\n    print('c result', r)\nit = c()\nprint(next(it))\nprint(it.send(1))\ntry:\n    it.send(2)\nexcept StopIteration:\n    pass", "a1\na got 1\nb1\nb got 2\nc result a-result/b", TestName = "yield_from_nested_chain")]
        [TestCase("def g():\n    try:\n        try:\n            yield 1\n        finally:\n            print('inner finally')\n    except ValueError:\n        print('outer except')\n        yield 'handled'\n    finally:\n        print('outer finally')\nit = g()\nnext(it)\nprint(it.throw(ValueError()))\nit.close()\nprint('end')", "inner finally\nouter except\nhandled\nouter finally\nend", TestName = "generator_throw_then_finally_order")]
        [TestCase("class Stop(Exception): pass\ndef worker():\n    n = 0\n    try:\n        while True:\n            try:\n                cmd = yield n\n            except Stop:\n                print('stopping at', n)\n                return n\n            n += 1\n    finally:\n        print('worker cleanup')\nw = worker()\nnext(w)\nw.send(None); w.send(None)\ntry:\n    w.throw(Stop())\nexcept StopIteration as e:\n    print('value', e.value)", "stopping at 2\nworker cleanup\nvalue 2", TestName = "generator_loop_with_throw_to_stop")]
